from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, in input order.

    Parities are computed in parallel with a thread pool. The result order
    matches the input order regardless of the number of workers.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([7]) == [1]
    assert parities([8]) == [0]


def test_parities_negative_and_zero() -> None:
    assert parities([-3, -2, -1, 0]) == [1, 0, 1, 0]


def test_parities_large_ints() -> None:
    big = 10**30
    assert parities([big, big + 1, -big - 1]) == [0, 1, 1]


def test_parities_preserves_order_large_input() -> None:
    xs = [(i * 7919) % 1009 for i in range(5000)]
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_order_not_scrambled_by_pattern() -> None:
    xs = [0] * 100 + [1] * 100 + [0, 1] * 100
    assert parities(xs) == xs


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 4, 3]
    parities(xs)
    assert xs == [5, 4, 3]


def test_parities_returns_new_list_of_ints() -> None:
    xs = [2, 3]
    out = parities(xs)
    assert out is not xs
    assert all(type(v) is int for v in out)
